import React, { useEffect, useState } from 'react';
import { useAuth } from '../../context/AuthContext';
import api from '../../api/axios';

export default function PageAlertes() {
  const { user }  = useAuth();
  const [alertes, setAlertes]         = useState([]);
  const [machines, setMachines]       = useState([]);
  const [loading, setLoading]         = useState(true);
  const [filtre, setFiltre]           = useState('TOUS');
  const [machineFiltree, setMachineFiltree] = useState('TOUTES');

  useEffect(() => {
    Promise.all([api.get('/alertes'), api.get('/machines')]).then(([a, m]) => {
      setAlertes(a.data);
      setMachines(m.data);
      setLoading(false);
    });
  }, []);

  const acquitter = async (id) => {
    try {
      await api.post(`/alertes/${id}/acquitter`, { utilisateur_id: user?.id });
      setAlertes(prev => prev.map(a => a.id === id ? { ...a, acquittee: 1 } : a));
    } catch(e) {
      alert('Erreur lors de l\'acquittement');
    }
  };

  const acquitterTout = async () => {
    if (!window.confirm('Acquitter toutes les alertes actives ?')) return;
    const actives = alertes.filter(a => !a.acquittee);
    await Promise.all(actives.map(a =>
      api.post(`/alertes/${a.id}/acquitter`, { utilisateur_id: user?.id })
    ));
    setAlertes(prev => prev.map(a => ({ ...a, acquittee: 1 })));
  };

  const filtrees = alertes.filter(a => {
    if (machineFiltree !== 'TOUTES' && a.machine_id !== parseInt(machineFiltree)) return false;
    if (filtre === 'ACTIVES')    return !a.acquittee;
    if (filtre === 'ACQUITTEES') return a.acquittee;
    if (filtre === 'CRITIQUE')   return a.niveau === 'CRITIQUE';
    if (filtre === 'WARNING')    return a.niveau === 'WARNING';
    return true;
  });

  const critique = alertes.filter(a => a.niveau === 'CRITIQUE' && !a.acquittee).length;
  const warning  = alertes.filter(a => a.niveau === 'WARNING'  && !a.acquittee).length;
  const actives  = alertes.filter(a => !a.acquittee).length;

  const niveauStyle = {
    CRITIQUE: { background:'rgba(255,71,87,0.15)',  color:'#ff4757', border:'1px solid rgba(255,71,87,0.25)' },
    WARNING:  { background:'rgba(245,166,35,0.15)', color:'#f5a623', border:'1px solid rgba(245,166,35,0.25)' },
    INFO:     { background:'rgba(0,153,255,0.15)',  color:'#0099ff', border:'1px solid rgba(0,153,255,0.25)' },
  };

  const niveauDot = { CRITIQUE:'#ff4757', WARNING:'#f5a623', INFO:'#0099ff' };

  if (loading) return <div style={S.loading}>Chargement...</div>;

  return (
    <div>
      {/* Métriques */}
      <div style={S.metricsRow}>
        {[
          { label:'CRITIQUES ACTIVES', val:critique, color:'#ff4757', status: critique > 0 ? 'Action requise' : 'Aucune', ok: critique === 0 },
          { label:'WARNINGS ACTIFS',   val:warning,  color:'#f5a623', status: warning  > 0 ? 'À surveiller'   : 'Aucun',  ok: warning  === 0 },
          { label:'NON ACQUITTÉES',    val:actives,  color:'#0099ff', status:`sur ${alertes.length} alertes`,  ok: actives  === 0 },
          { label:'ACQUITTÉES',        val:alertes.length - actives, color:'#2ed573', status:'Traitées', ok: true },
        ].map(m => (
          <div key={m.label} style={S.mcard}>
            <div style={{...S.mcardBar, background: m.color}}/>
            <div style={S.mcardLabel}>{m.label}</div>
            <div style={S.mcardVal}>{m.val}</div>
            <div style={S.mcardStatus}>
              <span style={{...S.dot, background: m.ok ? '#2ed573' : m.color}}/>
              <span style={{fontSize:11, color: m.ok ? '#2ed573' : m.color}}>{m.status}</span>
            </div>
          </div>
        ))}
      </div>

      {/* Filtres machines — boutons cliquables */}
      <div style={S.machineRow}>
        <button
          style={{...S.machineBtn, ...(machineFiltree==='TOUTES' ? S.machineBtnActive : {})}}
          onClick={() => setMachineFiltree('TOUTES')}
        >
          <span style={{...S.machineDot, background:'#00d4aa'}}/>
          Toutes les machines
        </button>
        {machines.map(m => (
          <button
            key={m.id}
            style={{...S.machineBtn, ...(machineFiltree===String(m.id) ? S.machineBtnActive : {})}}
            onClick={() => setMachineFiltree(String(m.id))}
          >
            <span style={{
              ...S.machineDot,
              background: m.statut==='EN SERVICE' ? '#2ed573' : '#ff4757'
            }}/>
            {m.nom}
          </button>
        ))}
      </div>

      {/* Filtres niveau + bouton acquitter tout */}
      <div style={S.toolbar}>
        <div style={S.filtres}>
          {['TOUS','ACTIVES','CRITIQUE','WARNING','ACQUITTEES'].map(f => (
            <button
              key={f}
              style={{...S.filtreBtn, ...(filtre===f ? S.filtreBtnActive : {})}}
              onClick={() => setFiltre(f)}
            >
              {f === 'CRITIQUE' && <span style={{...S.filtreDot, background:'#ff4757'}}/>}
              {f === 'WARNING'  && <span style={{...S.filtreDot, background:'#f5a623'}}/>}
              {f}
            </button>
          ))}
        </div>
        {actives > 0 && user?.role !== 'operateur' && (
          <button style={S.btnAcquitterTout} onClick={acquitterTout}>
            ✓ Acquitter tout ({actives})
          </button>
        )}
      </div>

      {/* Compteur résultats */}
      <div style={S.resultCount}>
        {filtrees.length} alerte(s) affichée(s)
        {machineFiltree !== 'TOUTES' && (
          <span style={S.resultTag}>
            {machines.find(m => String(m.id) === machineFiltree)?.nom}
            <button style={S.clearBtn} onClick={() => setMachineFiltree('TOUTES')}>✕</button>
          </span>
        )}
        {filtre !== 'TOUS' && (
          <span style={S.resultTag}>
            {filtre}
            <button style={S.clearBtn} onClick={() => setFiltre('TOUS')}>✕</button>
          </span>
        )}
      </div>

      {/* Liste alertes */}
      <div style={S.card}>
        {filtrees.length === 0 ? (
          <div style={S.empty}>Aucune alerte trouvée</div>
        ) : (
          filtrees.map(a => (
            <div key={a.id} style={{...S.alertItem, opacity: a.acquittee ? 0.45 : 1}}>
              <div style={{
                ...S.alertDot,
                background: niveauDot[a.niveau] || '#7a8394',
                boxShadow: !a.acquittee && a.niveau==='CRITIQUE' ? `0 0 8px ${niveauDot[a.niveau]}` : 'none'
              }}/>
              <div style={{flex:1}}>
                <div style={S.alertMsg}>{a.message}</div>
                <div style={S.alertMeta}>
                  <span style={{...S.pill, ...niveauStyle[a.niveau]}}>{a.niveau}</span>
                  {a.valeur && (
                    <span style={S.alertVal}>
                      Valeur : <strong>{parseFloat(a.valeur).toFixed(2)}</strong>
                      {a.seuil && <> / Seuil : <strong>{parseFloat(a.seuil).toFixed(2)}</strong></>}
                    </span>
                  )}
                  <span style={S.alertTime}>
                    {new Date(a.cree_le).toLocaleString('fr-FR')}
                  </span>
                </div>
              </div>
              {!a.acquittee ? (
                user?.role !== 'operateur' ? (
                  <button style={S.btnAcquitter} onClick={() => acquitter(a.id)}>Acquitter</button>
                ) : (
                  <span style={S.nonAcquittee}>En attente</span>
                )
              ) : (
                <span style={S.acquittee}>✓ Acquittée</span>
              )}
            </div>
          ))
        )}
      </div>
    </div>
  );
}

const S = {
  loading:         { color:'#7a8394', textAlign:'center', marginTop:40 },
  metricsRow:      { display:'grid', gridTemplateColumns:'repeat(4,1fr)', gap:14, marginBottom:20 },
  mcard:           { background:'#161b22', border:'1px solid rgba(255,255,255,0.07)', borderRadius:10, padding:'18px 20px', position:'relative', overflow:'hidden' },
  mcardBar:        { position:'absolute', top:0, left:0, right:0, height:2 },
  mcardLabel:      { fontFamily:'segoe UI', fontSize:10, color:'#4a5260', letterSpacing:1.5, textTransform:'uppercase', marginBottom:12 },
  mcardVal:        { fontSize:28, fontWeight:600, color:'#e8eaf0', fontFamily:'segoe UI' },
  mcardStatus:     { display:'flex', alignItems:'center', gap:5, marginTop:8 },
  dot:             { width:5, height:5, borderRadius:'50%', flexShrink:0 },

  // Machines — boutons
  machineRow:      { display:'flex', gap:8, flexWrap:'wrap', marginBottom:14 },
  machineBtn:      { display:'flex', alignItems:'center', gap:7, padding:'7px 14px', background:'rgba(255,255,255,0.03)', border:'1px solid rgba(255,255,255,0.08)', borderRadius:20, color:'#7a8394', fontSize:12, cursor:'pointer', fontFamily:'segoe UI', transition:'all 0.15s', whiteSpace:'nowrap' },
  machineBtnActive:{ background:'rgba(0,212,170,0.10)', borderColor:'rgba(0,212,170,0.30)', color:'#00d4aa' },
  machineDot:      { width:6, height:6, borderRadius:'50%', flexShrink:0, display:'inline-block' },

  // Filtres niveau
  toolbar:         { display:'flex', alignItems:'center', justifyContent:'space-between', marginBottom:10 },
  filtres:         { display:'flex', gap:6, flexWrap:'wrap' },
  filtreBtn:       { display:'flex', alignItems:'center', gap:5, padding:'6px 12px', background:'transparent', border:'1px solid rgba(255,255,255,0.10)', borderRadius:6, color:'#7a8394', fontSize:11, cursor:'pointer', fontFamily:'segoe UI', transition:'all 0.15s' },
  filtreBtnActive: { background:'rgba(0,212,170,0.10)', borderColor:'rgba(0,212,170,0.30)', color:'#00d4aa' },
  filtreDot:       { width:5, height:5, borderRadius:'50%', flexShrink:0 },
  btnAcquitterTout:{ padding:'7px 14px', background:'rgba(46,213,115,0.10)', border:'1px solid rgba(46,213,115,0.25)', borderRadius:7, color:'#2ed573', fontSize:12, cursor:'pointer', fontFamily:'segoe UI' },

  // Compteur
  resultCount:     { fontSize:12, color:'#4a5260', marginBottom:12, display:'flex', alignItems:'center', gap:8 },
  resultTag:       { display:'flex', alignItems:'center', gap:4, padding:'2px 8px', background:'rgba(0,212,170,0.08)', border:'1px solid rgba(0,212,170,0.20)', borderRadius:4, color:'#00d4aa', fontSize:11, fontFamily:'segoe UI' },
  clearBtn:        { background:'none', border:'none', color:'#00d4aa', cursor:'pointer', fontSize:12, padding:'0 0 0 4px', lineHeight:1 },

  // Liste
  card:            { background:'#161b22', border:'1px solid rgba(255,255,255,0.07)', borderRadius:10, padding:'20px 22px' },
  empty:           { color:'#7a8394', textAlign:'center', padding:'40px 0', fontSize:13 },
  alertItem:       { display:'flex', alignItems:'center', gap:14, padding:'16px 0', borderBottom:'1px solid rgba(255,255,255,0.05)' },
  alertDot:        { width:8, height:8, borderRadius:'50%', flexShrink:0 },
  alertMsg:        { fontSize:13, color:'#e8eaf0', marginBottom:8, fontWeight:500 },
  alertMeta:       { display:'flex', alignItems:'center', gap:12, flexWrap:'wrap' },
  alertVal:        { fontSize:11, color:'#7a8394', fontFamily:'segoe UI' },
  alertTime:       { fontSize:11, color:'#4a5260', fontFamily:'segoe UI' },
  pill:            { display:'inline-flex', fontFamily:'segoe UI', fontSize:10, padding:'3px 8px', borderRadius:4 },
  btnAcquitter:    { padding:'6px 14px', background:'rgba(0,212,170,0.10)', border:'1px solid rgba(0,212,170,0.25)', borderRadius:6, color:'#00d4aa', fontSize:12, cursor:'pointer', flexShrink:0, fontFamily:'segoe UI' },
  acquittee:       { fontSize:11, color:'#2ed573', fontFamily:'segoe UI', flexShrink:0 },
  nonAcquittee:    { fontSize:11, color:'#f5a623', fontFamily:'segoe UI', flexShrink:0 },
};
